parameters.jsCode:
const crypto = require('crypto');
const input = $('Webhook').first().json;
const resolved = $('Resolve Config').first().json;

const document_id = input.body?.document_id || input.document_id;
if (!document_id) {
  throw new Error('document_id is required');
}

// Config con resolución 3-layer
const config = {
  SUPABASE_URL: 'https://hvlsuwdqtffiilvampxq.supabase.co',
  N8N_WEBHOOK_BASE: 'https://mmenendeza.app.n8n.cloud',
  CLAUSE_REVIEW_ENDPOINT: '/webhook/clause-review-nueva-planta',
  CLAUSE_TIMEOUT: 120000,
  // 3-Layer resolution
  blueprint_version_id: resolved?.blueprint_version_id || null,
  contract_model_version_id: resolved?.contract_model_version_id || null,
  blueprint_name: resolved?.blueprint_name || 'Default',
  contract_type: input.body?.contract_type || 'nueva_planta'
};

return [{
  json: {
    run_id: crypto.randomUUID(),
    document_id,
    config,
    started_at: new Date().toISOString()
  }
}];

// Parse LLM response and prepare clauses
const crypto = require('crypto');
const runData = $('Create Run ID').first().json;
const document = $('Fetch Document').first().json;
let extractedData = { clauses: [] };

try {
  const llmResponse = $('LLM Extract Clauses').first().json;
  const content = llmResponse.choices?.[0]?.message?.content || '{}';
  extractedData = JSON.parse(content);
} catch (e) {
  console.log('LLM parse error:', e.message);
  // Fallback: crear una cláusula genérica si el parsing falla
  extractedData = {
    clauses: [{
      clause_number: '1',
      heading: 'Documento Completo',
      clause_text: document.raw_content?.substring(0, 5000) || 'No content',
      probable_category: 'OTRO'
    }]
  };
}

if (!extractedData.clauses || extractedData.clauses.length === 0) {
  throw new Error('No clauses extracted from document');
}

// Map clauses with run context and 3-layer info
const clauses = extractedData.clauses.map((c, idx) => ({
  clause_id: `clause_${idx + 1}`,
  clause_instance_id: crypto.randomUUID(),
  sequence_number: idx + 1,
  clause_number: c.clause_number,
  heading: c.heading,
  clause_text: c.clause_text,
  probable_category: c.probable_category,
  // Run context
  run_id: runData.run_id,
  document_id: runData.document_id,
  // 3-Layer context
  blueprint_version_id: runData.config.blueprint_version_id,
  contract_model_version_id: runData.config.contract_model_version_id
}));

console.log(`Extracted ${clauses.length} clauses from document`);

return clauses.map(c => ({ json: c }));

// Fallback: usar cláusulas de prueba cuando no hay contenido
const crypto = require('crypto');
const runData = $('Create Run ID').first().json;

console.log('WARNING: No document content found. Using sample clauses for testing.');

const sampleClauses = [
  {
    clause_number: '1.1',
    heading: 'Precio del Contrato',
    clause_text: 'El precio total del contrato es de 15.000.000 EUR. El pago se realizará en 3 plazos: 30% a la firma, 40% al 50% de avance, y 30% a la recepción definitiva.',
    probable_category: 'PRECIO_PAGOS'
  },
  {
    clause_number: '2.1',
    heading: 'Alcance de los Trabajos',
    clause_text: 'El Contratista ejecutará todos los trabajos necesarios para la completa construcción de la planta, incluyendo cualquier trabajo adicional que sea requerido por el Propietario.',
    probable_category: 'ALCANCE_TRABAJO'
  },
  {
    clause_number: '3.1',
    heading: 'Responsabilidades',
    clause_text: 'El Contratista será responsable de todos los daños que se produzcan durante la ejecución de las obras, sin limitación alguna.',
    probable_category: 'RESPONSABILIDADES'
  },
  {
    clause_number: '4.1',
    heading: 'Hitos y Penalizaciones',
    clause_text: 'El retraso en cualquier hito conllevará penalizaciones del 1% semanal sin límite máximo.',
    probable_category: 'ENTREGABLES_HITOS'
  },
  {
    clause_number: '5.1',
    heading: 'Terminación',
    clause_text: 'El Propietario podrá resolver el contrato en cualquier momento y por cualquier causa, sin derecho a indemnización para el Contratista.',
    probable_category: 'TERMINACION'
  }
];

const clauses = sampleClauses.map((c, idx) => ({
  clause_id: `clause_${idx + 1}`,
  clause_instance_id: crypto.randomUUID(),
  sequence_number: idx + 1,
  clause_number: c.clause_number,
  heading: c.heading,
  clause_text: c.clause_text,
  probable_category: c.probable_category,
  run_id: runData.run_id,
  document_id: runData.document_id,
  blueprint_version_id: runData.config.blueprint_version_id,
  contract_model_version_id: runData.config.contract_model_version_id,
  is_sample: true
}));

return clauses.map(c => ({ json: c }));

// Aggregate contract-level decision
const results = $json.results || [];
const runData = $('Create Run ID').first().json;

let hasBlock = false;
let hasRequired = false;
let escalations = [];

const stateCounts = { OK: 0, RECOMMENDED: 0, REQUIRED: 0, NEEDS_REVIEW: 0, BLOCKED: 0 };

for (const r of results) {
  const state = r.client_state || 'NEEDS_REVIEW';
  stateCounts[state] = (stateCounts[state] || 0) + 1;

  if (state === 'BLOCKED') hasBlock = true;
  if (state === 'REQUIRED') {
    hasRequired = true;
    escalations.push({ clause_id: r.clause_id, reason: r.escalation_reason || 'Requires review' });
  }
}

let contract_decision = 'READY_FOR_EXPORT';
if (hasBlock) contract_decision = 'BLOCKED';
else if (hasRequired) contract_decision = 'NEEDS_REVIEW';

return [{
  json: {
    results,
    run_id: runData.run_id,
    document_id: runData.document_id,
    contractDecision: {
      contract_decision,
      escalations_pending: escalations.length,
      state_counts: stateCounts
    },
    escalations,
    total_clauses: results.length
  }
}];

